44	const PROCESSING_FEE = 5;
45	
46	// Only the main item types. Components are priced separately: individually,
47	// or as a discounted block of 3 alike ones.
48	const BASE_PREMIUMS: Record<string, number> = {
49	  sword: 100,
50	  amulet: 60,
51	  staff: 80,
52	  potion: 40,
53	};
54	
55	// Insurance values are the SUM INSURED per item - distinct from the base
56	// premiums above, which price the policy.
57	const INSURANCE_VALUES: Record<string, number> = {
58	  sword: 1000,
59	  amulet: 600,
60	  staff: 800,
61	  potion: 400,
62	};
63	
64	const COMPONENT_INSURANCE_VALUE = 250;
65	const DEDUCTIBLE_PER_DAMAGE = 100;
66	const CAP_MULTIPLE = 2;
67	
68	const COMPONENT_TYPES = ["rune", "moonstone"];
69	const COMPONENT_BASE_PREMIUM = 25;
70	const BLOCK_SIZE = 3;
71	const BLOCK_BASE_PREMIUM = 60;
72	
73	const isComponent = (item: Item): boolean =>
74	  COMPONENT_TYPES.includes(item.type);
75	
76	// Modifiers are additive percentages of the UNMODIFIED base premium, never
77	// compounding multipliers, and are kept as exact fractions rather than float
78	// multipliers: 100 * 1.1 is 110.00000000000001 in IEEE-754. Only the final
79	// premium is rounded, so intermediate amounts stay fractional.
80	const percentOf = (amount: number, percent: number): number =>
81	  (amount * percent) / 100;
82	
83	// Modifiers are signed terms in one additive sum, so a discount is simply a
84	// negative percentage. Naming the sign keeps it from riding on a single easily
85	// overlooked "-" at a call site.
86	const discountOf = (amount: number, percent: number): number =>
87	  -percentOf(amount, percent);
88	
89	const FIRST_INSURANCE_PERCENT = 10;
90	const CURSE_PERCENT = 50;
91	const HIGH_ENCHANTMENT_PERCENT = 30;
92	const HIGH_ENCHANTMENT_THRESHOLD = 5;
93	const LOYALTY_DISCOUNT_PERCENT = 20;
94	const LOYALTY_THRESHOLD_YEARS = 2;
95	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
96	
97	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
98	
99	// A group of exactly 3 alike components is offered at a block price. Any
100	// other count is priced per component.
101	const componentGroupPremium = (count: number): number =>
102	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
103	
104	// Components are priced per group of alike ones, so each distinct type is
105	// counted and priced on its own.
106	const componentsPremium = (components: Item[]): number => {
107	  const distinctTypes = new Set(components.map((component) => component.type));
108	
109	  return [...distinctTypes].reduce((sum, type) => {
110	    const alike = components.filter((component) => component.type === type);
111	    return sum + componentGroupPremium(alike.length);
112	  }, 0);
113	};
114	
115	// Splits a quote's items into the two independently-priced kinds, so the
116	// main/component distinction is decided in exactly one place.
117	const partitionByComponent = (
118	  items: Item[],
119	): { mainItems: Item[]; components: Item[] } => ({
120	  mainItems: items.filter((item) => !isComponent(item)),
121	  components: items.filter(isComponent),
122	});
123	
124	// Item-specific modifiers apply to the affected item's OWN base premium, not
125	// to the policy total. They are independent: a cursed, highly enchanted item
126	// carries both, so each item sums the surcharges that apply to it.
127	const isHighlyEnchanted = (item: Item): boolean =>
128	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
129	
130	const surchargesFor = (item: Item): number => {
131	  const base = basePremiumOf(item);
132	  const curse = item.cursed ? percentOf(base, CURSE_PERCENT) : 0;
133	  const enchantment = isHighlyEnchanted(item)
134	    ? percentOf(base, HIGH_ENCHANTMENT_PERCENT)
135	    : 0;
136	
137	  return curse + enchantment;
138	};
139	
140	const itemSpecificModifiers = (mainItems: Item[]): number =>
141	  mainItems.reduce((sum, item) => sum + surchargesFor(item), 0);
142	
143	// Policy-wide modifiers are percentages of the whole policy's base premium,
144	// taken from the UNMODIFIED base so item-specific modifiers never feed into
145	// them - that is what keeps modifiers additive instead of compounding.
146	// Discounts are negative terms.
147	const qualifiesForLoyalty = (customer: Customer): boolean =>
148	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
149	
150	const policyWideModifiers = (
151	  basePremium: number,
152	  customer: Customer,
153	  isFollowUp: boolean,
154	): number => {
155	  // First insurance applies to every quote, including follow-ups: the spec
156	  // treats each item in a quote as a first insurance regardless of customer
157	  // history, so this coexists with the follow-up discount.
158	  const firstInsurance = percentOf(basePremium, FIRST_INSURANCE_PERCENT);
159	  const loyalty = qualifiesForLoyalty(customer)
160	    ? discountOf(basePremium, LOYALTY_DISCOUNT_PERCENT)
161	    : 0;
162	  const followUp = isFollowUp
163	    ? discountOf(basePremium, FOLLOW_UP_DISCOUNT_PERCENT)
164	    : 0;
165	
166	  return firstInsurance + loyalty + followUp;
167	};
168	
169	// Amounts are rounded in the MHPCO's favor, and the direction depends on who
170	// pays: a premium is owed TO MHPCO, so it rounds up. (A payout is owed BY
171	// MHPCO, so it will round down - hence the rule, not the direction, is what
172	// this name states.) Applied once, where a step's result is emitted: every
173	// amount inside the pricing pipeline stays an exact fraction.
174	const roundPremiumInMhpcoFavor = (premium: number): number =>
175	  Math.ceil(premium);
176	
177	// Returns the EXACT, unrounded premium. Rounding happens once, at the point
178	// the result is emitted - see runScenario.
179	const quotePremium = (
180	  step: QuoteStep,
181	  customer: Customer,
182	  isFollowUp: boolean,
183	): number => {
184	  const { mainItems, components } = partitionByComponent(step.items);
185	
186	  const basePremium =
187	    mainItems.reduce((sum, item) => sum + basePremiumOf(item), 0) +
188	    componentsPremium(components);
189	
190	  const modifiers =
191	    itemSpecificModifiers(mainItems) +
192	    policyWideModifiers(basePremium, customer, isFollowUp);
193	
194	  return basePremium + modifiers + PROCESSING_FEE;
195	};
196	
197	const insuranceValueOf = (item: Item): number =>
198	  isComponent(item) ? COMPONENT_INSURANCE_VALUE : INSURANCE_VALUES[item.type];
199	
200	// The insurance sum is a plain per-item total: the component block discount
201	// affects the premium only, never the sum insured.
202	const insuranceSumOf = (items: Item[]): number =>
203	  items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
204	
205	// A policy remembers what it covers and how much of its cap is left, so later
206	// claim steps can draw against it.
207	type Policy = {
208	  items: Item[];
209	  remainingCap: number;
210	};
211	
212	const openPolicy = (items: Item[]): Policy => ({
213	  items,
214	  remainingCap: CAP_MULTIPLE * insuranceSumOf(items),
215	});
216	
217	// Each damage entry carries its own deductible.
218	const payoutForDamage = (damage: Damage): number =>
219	  damage.amount - DEDUCTIBLE_PER_DAMAGE;
220	
221	const settleClaim = (policy: Policy, incident: Incident): number =>
222	  incident.damages.reduce(
223	    (total, damage) => total + payoutForDamage(damage),
224	    0,
225	  );
226	
227	export const runScenario = (scenario: Scenario): ScenarioResult => {
228	  // Policies are keyed by the step index of the quote that created them, which
229	  // is how claim steps reference them.
230	  const policies = new Map<number, Policy>();
231	
232	  // The follow-up discount depends on how many QUOTES preceded this one, which
233	  // is not the step index once claim steps are interleaved.
234	  let quotesSoFar = 0;
235	
236	  const results = scenario.steps.map((step, stepIndex) => {
237	    if (step.op === "claim") {
238	      const policy = policies.get(step.policy) as Policy;
239	      const payout = settleClaim(policy, step.incident);
240	
241	      policy.remainingCap -= payout;
242	
243	      return { payout, remainingCap: policy.remainingCap };
244	    }
245	
246	    policies.set(stepIndex, openPolicy(step.items));
247	
248	    const premium = roundPremiumInMhpcoFavor(
249	      quotePremium(step, scenario.customer, quotesSoFar > 0),
250	    );
251	    quotesSoFar += 1;
252	
253	    return { premium };
254	  });
255	
256	  return { results };
257	};
